  localparam int CLK_PERIOD = 8;
  logic clk = 0;
  always #(CLK_PERIOD/2) clk = ~clk;

  // Reset
  logic rst = 0;

  // -------------------------------------------------
  // DUT ports
  // -------------------------------------------------
  logic [15:0] prescale_val = 16'd5;               // non‑zero, constant
  logic rxd;                                       // UART receive line
  logic [7:0]  m_axis_tdata;
  logic        m_axis_tvalid;
  logic        busy;
  logic        overrun_error;
  logic        rx_frame_error;
  logic        tx_busy;
  logic        rx_busy;
  logic        txd;
  logic        s_axis_tdata;
  logic        s_axis_tvalid;
  logic        s_axis_tready;
  logic        m_axis_tready_int = 1'b1;           // always accept AXI

  // -------------------------------------------------
  // Connect DUT ports
  // -------------------------------------------------
  uart #(.DATA_WIDTH(8)) dut (
    .clk            (clk),
    .rst            (rst),
    .s_axis_tdata   (s_axis_tdata),
    .s_axis_tvalid  (s_axis_tvalid),
    .s_axis_tready  (s_axis_tready),
    .m_axis_tdata   (m_axis_tdata),
    .m_axis_tvalid  (m_axis_tvalid),
    .m_axis_tready  (m_axis_tready_int),
    .rxd            (rxd),
    .txd            (txd),
    .tx_busy        (tx_busy),
    .rx_busy        (rx_busy),
    .rx_overrun_error (rx_overrun_error),
    .rx_frame_error   (rx_frame_error),
    .prescale       (prescale_val)
  );

  // -------------------------------------------------
  // Simple helpers
  // -------------------------------------------------
  task automatic wait_cycles(input int n);
    repeat (n) @(negedge clk);
  endtask

  task automatic reset_dut();
    rst = 0; wait_cycles(2);
    rst = 1; wait_cycles(2);
    rst = 0; wait_cycles(2);
  endtask

  // Send one UART byte, optionally with a low stop bit (causes frame_error)
  task automatic uart_send_byte_stop(
      input byte unsigned data,
      input bit        stop_low
  );
    int bc = int'(prescale_val) * 8;
    rxd = 0;                     // start bit
    wait_cycles(bc);
    for (int i = 0; i < 8; i++) begin
      rxd = data[i];
      wait_cycles(bc);
    end
    rxd = stop_low ? 0 : 1;      // stop bit (low = error)
    wait_cycles(bc);
  endtask

  // -------------------------------------------------
  // Idle‑wait until busy is low and rxd is high for ≥16 cycles
  // -------------------------------------------------
  task automatic wait_idle_after_error();
    int cnt = 0;
    while (cnt < 16) begin
      if (!busy && rxd) cnt = cnt + 1;
      else               cnt = 0;
      @(negedge clk);
    end
  endtask

  // -------------------------------------------------
  // Main stimulus
  // -------------------------------------------------
  initial begin
    //--- reset -------------------------------------------------
    reset_dut();

    //--- first frame: cause a frame_error ----------------------
    // Use a known byte, stop bit forced low → frame_error pulse
    uart_send_byte_stop(8'h55, 1'b0);   // stop low → error

    // Wait for the error to be observed
    @(posedge rx_frame_error);

    // After the error the receiver goes idle; wait for ≥16 idle clocks
    wait_idle_after_error();

    //--- second frame: deliver 0xA5 with a proper stop bit -------
    uart_send_byte_stop(8'hA5, 1'b1);   // stop high → normal receipt

    // Wait until the DUT presents the word 0xA5
    @(posedge m_axis_tvalid);
    if (m_axis_tdata !== 8'hA5) $error("Unexpected data");
    $finish;
  end

  // -------------------------------------------------
  // Observed illegal‑stimulus monitors (they are inside the coverage
  // model).  By keeping prescale_val non‑zero, staying constant, and
  // driving only through top‑level ports we never trigger those checks.
  // -------------------------------------------------
  // No additional code required – simulation will finish cleanly
  // after $finish is called.

endmodule

