    .clk               (clk),
    .rst               (rst),
    .s_axis_tdata      (s_axis_tdata),
    .s_axis_tvalid     (s_axis_tvalid),
    .s_axis_tready     (),                 // unused output, leave unconnected
    .txd               (txd),
    .rxd               (rxd),
    .tx_busy           (tx_busy),
    .rx_busy           (rx_busy),
    .rx_overrun_error  (rx_overrun_error),
    .rx_frame_error    (rx_frame_error),
    .prescale          (prescale)
  );

  // -------------------------------------------------
  // Reset sequence
  // -------------------------------------------------
  initial begin
    #1 rst = 1'b0;               // deassert reset after a few cycles
    #(CLK_PERIOD*2);
    rst = 1'b1;
    #(CLK_PERIOD*2);
    rst = 1'b0;
    #(CLK_PERIOD*2);
  end

  // -------------------------------------------------
  // Create a frame error, then idle for ≥16 clocks
  // -------------------------------------------------
  initial begin
    // Wait until reset is released
    @(negedge rst);
    #1;

