    // Deliver a fresh frame that contains 8'hA5
    // -------------------------------------------------
    s_axis_tvalid = 1'b1;
    s_axis_tdata  = 8'hA5;

    // Give the DUT enough time to serialize the byte and present it on the AXI output
    #10000;                                      // sufficient for one frame transmission

    $finish;                                     // clean termination
  end

